class CircuitRedis{public function __construct(public string $role){}public function get(string $key){$GLOBALS['calls'][]=['role'=>$this->role,'args'=>['GET',$key]];if(!empty($GLOBALS['scenario']['get_error']))throw new RuntimeException('declared GET failure');$state=$GLOBALS['scenario']['state']??null;return $state===null?false:(is_string($state)?$state:json_encode($state));}public function set(string $key,string $value,array $options=[]):bool{$args=['SET',$key,$value];foreach($options as $k=>$v){if(is_int($k))$args[]=strtoupper($v);else{$args[]=strtoupper($k);$args[]=(string)$v;}}$GLOBALS['calls'][]=['role'=>$this->role,'args'=>$args];return $this->role==='queue'?($GLOBALS['scenario']['lock']??true):true;}public function hIncrBy(string $key,string $field,int $value):int{$GLOBALS['calls'][]=['role'=>$this->role,'args'=>['HINCRBY',$key,$field,(string)$value]];if(!empty($GLOBALS['scenario']['h_error']))throw new RuntimeException('declared hash counter error');return 1;}public function hIncrByFloat(string $key,string $field,float $value):float{$GLOBALS['calls'][]=['role'=>$this->role,'args'=>['HINCRBYFLOAT',$key,$field,(string)$value]];return $value;}public function hGet(string $key,string $field):string{$GLOBALS['calls'][]=['role'=>$this->role,'args'=>['HGET',$key,$field]];return (string)($GLOBALS['scenario']['max']??0);}public function hSet(string $key,string $field,string $value):int{$GLOBALS['calls'][]=['role'=>$this->role,'args'=>['HSET',$key,$field,$value]];return 1;}public function lPush(string $key,string $value):int{$GLOBALS['calls'][]=['role'=>$this->role,'args'=>['LPUSH',$key,$value]];return 1;}public function lTrim(string $key,int $start,int $end):bool{$GLOBALS['calls'][]=['role'=>$this->role,'args'=>['LTRIM',$key,(string)$start,(string)$end]];return true;}public function del(array $keys):int{$GLOBALS['calls'][]=['role'=>$this->role,'args'=>array_merge(['DEL'],$keys)];return count($keys);}public function incrBy(string $key,int $n):int{$GLOBALS['calls'][]=['role'=>$this->role,'args'=>['INCRBY',$key,(string)$n]];return 1;}public function expire(string $key,int $ttl):bool{$GLOBALS['calls'][]=['role'=>$this->role,'args'=>['EXPIRE',$key,(string)$ttl]];return true;}}
function ap_redis_client(string $purpose='cache'){return !empty($GLOBALS['scenario']['unavailable'])?null:new CircuitRedis($purpose);}
function circuit_time():int{return 1791700200;}
$hashes=[];foreach(['ap_redis_json_get','ap_redis_json_set','ap_redis_delete','ap_redis_metric_inc','ap_redis_lock','ap_provider_circuit_key','ap_provider_circuit_allow','ap_provider_circuit_success','ap_provider_circuit_failure','ap_timing_record'] as $name){$source=(string)file_get_contents(dirname(__DIR__).'/ap-redis.php');if(!preg_match('/^function '.preg_quote($name,'/').'\(.*?^}/ms',$source,$m))throw new RuntimeException($name);$hashes[$name]=hash('sha256',$m[0]);eval(str_replace('time()','circuit_time()',$m[0]));}
$cases=[['name'=>'allow_missing','op'=>'allow'],['name'=>'allow_open','op'=>'allow','state'=>['open_until'=>1791700201]],['name'=>'allow_probe','op'=>'allow','state'=>['open_until'=>1791700200],'lock'=>true],['name'=>'deny_probe','op'=>'allow','state'=>['open_until'=>1],'lock'=>false],['name'=>'allow_bad_json','op'=>'allow','state'=>'invalid'],['name'=>'allow_get_error','op'=>'allow','get_error'=>true],['name'=>'failure_first','op'=>'failure'],['name'=>'failure_third','op'=>'failure','state'=>['failures'=>2]],['name'=>'failure_fifth','op'=>'failure','state'=>['failures'=>4]],['name'=>'failure_tenth','op'=>'failure','state'=>['failures'=>9]],['name'=>'success','op'=>'success'],['name'=>'unavailable_allow','op'=>'allow','unavailable'=>true],['name'=>'unavailable_failure','op'=>'failure','unavailable'=>true]];
if(getenv('PROFILE_PREVIEW_TIMING_ONLY')==='1')$cases=[['name'=>'new_max','op'=>'timing','ms'=>1.25],['name'=>'zero','op'=>'timing','ms'=>0],['name'=>'below_max','op'=>'timing','ms'=>2.75,'max'=>3],['name'=>'equal_max','op'=>'timing','ms'=>3,'max'=>3],['name'=>'small','op'=>'timing','ms'=>0.001],['name'=>'negative','op'=>'timing','ms'=>-1],['name'=>'unavailable','op'=>'timing','ms'=>1.5,'unavailable'=>true],['name'=>'hash_error','op'=>'timing','ms'=>1.5,'h_error'=>true]];
$provider=getenv('PROFILE_CIRCUIT_PROVIDER')?:'preview:public.test';$timing=getenv('PROFILE_CIRCUIT_TIMING')?:'link_preview.http';
$captures=[];foreach($cases as $case){$GLOBALS['scenario']=$case;$GLOBALS['calls']=[];$result=null;if($case['op']==='allow')$result=ap_provider_circuit_allow($provider);elseif($case['op']==='failure')ap_provider_circuit_failure($provider);elseif($case['op']==='timing')ap_timing_record($timing,$case['ms']);else ap_provider_circuit_success($provider);$captures[]=['case'=>$case,'result'=>$result,'commands'=>$GLOBALS['calls']];}
$out=$argv[1]??'/tmp/vaak-profile-preview-circuit-reference.json';file_put_contents($out,json_encode(['provider'=>$provider,'timing'=>$timing,'clock'=>circuit_time(),'captures'=>$captures,'declaration_sha256'=>$hashes,'scope'=>'Actual PHP circuit, lock, JSON and metric helpers; Redis method transport and clock declared recorders, no live Redis mutations. Native replay uses isolated RESP command transport.'],JSON_THROW_ON_ERROR|JSON_UNESCAPED_SLASHES));echo count($captures).' actual circuit controls '.$out."\n";
